  }

  get name() {
    return this._name;
  }

  set name(value) {
    if (value.length < 3) {
      throw new Error("Name is too short");
    }

    this._name = value;
  }
}

const user = new User("Jeet");

console.log(user.name); // Jeet

user.name = "John";
console.log(user.name); // John

