class User {
  constructor(name) {
    this.name = name;
  }

  greet() {
    return `Hello, ${this.name}`;
  }
}

const user = new User("Jeet");

console.log(Object.getPrototypeOf(user) === User.prototype);
// true

console.log(User.prototype.greet === user.greet);
// true

// The greet() method is shared through User.prototype.
